css:
/* ==========================================================================
   GUTTERLIGHT  -  a rain-soaked gothic city drawn as a crime comic.
   Structural idea: the app is a comic page. Every surface is an inked panel
   (square corners, one slanted edge) on a gutter; titles are caption boxes
   pinned in panel corners; your own turns are speech balloons with a tail;
   avatars are tilted inset close-ups; scene breaks become gutters.
   ========================================================================== */

/* ---------- 1. tokens ---------------------------------------------------- */
:root {
  --mari-tokens-version: 1;

  /* house fonts */
  --gl-display: "Big Shoulders", "Instrument Sans", Impact, sans-serif;
  --gl-ui: "Instrument Sans", system-ui, sans-serif;
  --gl-read: "Crimson Pro", Georgia, serif;
  --mari-font-ui: var(--gl-ui);
  --mari-font-heading: var(--gl-display);
  --mari-font-chat: var(--gl-read);

  /* panel geometry */
  --gl-frame: 3.5px;      /* ink frame */
  --gl-cut: clamp(12px, 13%, 36px); /* the slant scales with the panel: 36 px on long replies, about 14 px on one-liners */
  --gl-cut-pad: 30px;     /* bottom room for text above the slant (fixed: % padding would follow width) */
  --radius: 0px;

  /* NIGHT is the default */
  --gl-gutter: #07080a;
  --gl-paper: rgb(21 23 27 / 0.95);
  --gl-paper-solid: #15171b;
  --gl-paper-2: #1d2025;
  --gl-ink: #000000;
  --gl-key: rgb(240 176 74 / 0.28);     /* thin amber keyline inside night panels */
  --gl-text: #ece6d8;
  --gl-mute: #b5ad9c;
  --gl-dim: #8f8878;
  --gl-caption: #e9b44c;
  --gl-caption-ink: #111111;
  --gl-sodium: #f0b04a;
  --gl-neon: #3fd6c6;
  --gl-red: #ff5a4a;
  --gl-balloon: #ece7da;
  --gl-balloon-ink: #121214;
  --gl-line: rgb(236 230 216 / 0.16);
  --gl-halftone: url("theme:halftone-amber.png");
  --gl-grain: url("theme:grain-light.png");

  --background: var(--gl-gutter);
  --foreground: var(--gl-text);
  --card: var(--gl-paper);
  --card-foreground: var(--gl-text);
  --popover: var(--gl-paper-solid);
  --popover-foreground: var(--gl-text);
  --primary: var(--gl-sodium);
  --primary-foreground: #111111;
  --secondary: #23262c;
  --secondary-foreground: var(--gl-text);
  --muted: #1d2025;
  --muted-foreground: var(--gl-mute);
  --accent: #2a2d33;
  --accent-foreground: var(--gl-text);
  --destructive: #d8402f;
  --destructive-foreground: #ffffff;
  --border: rgb(236 230 216 / 0.2);
  --input: rgb(236 230 216 / 0.22);
  --ring: var(--gl-sodium);
  --sidebar: rgb(8 9 11 / 0.9);
  --sidebar-foreground: var(--gl-text);
  --sidebar-border: #000;
  --sidebar-accent: #23262c;
  --sidebar-accent-foreground: var(--gl-text);

  --ov-line: var(--gl-line);
  --ov-text: var(--gl-text);
  --ov-muted: var(--gl-mute);
  --ov-dim: var(--gl-dim);
  --ov-accent: var(--gl-sodium);
  --ov-hover: rgb(240 176 74 / 0.08);
  --ov-active-bg: rgb(240 176 74 / 0.14);
  --mari-selected-tint: var(--gl-sodium);
  --mari-chrome-accent: var(--gl-sodium);
  --mari-chrome-muted: var(--gl-mute);

  --ov-mode-conversation: var(--gl-neon);
  --ov-mode-roleplay: var(--gl-sodium);
  --ov-mode-game: var(--gl-red);
  --mari-mode-conversation: var(--gl-neon);
  --mari-mode-roleplay: var(--gl-sodium);
  --mari-mode-game: var(--gl-red);
  --mari-ctrlk-conversation: var(--gl-neon);
  --mari-ctrlk-roleplay: var(--gl-sodium);
  --mari-ctrlk-game: var(--gl-red);
  --mari-home-pink: var(--gl-red);
  --mari-home-violet: var(--gl-neon);
  --mari-resource-accent: var(--gl-sodium);

  --mari-status-online: #58d68d;
  --mari-status-idle: var(--gl-sodium);
  --mari-status-dnd: var(--gl-red);
  --mari-status-offline: #6d6a62;
  --mari-gauge-ok: #58c48a;
  --mari-gauge-warn: var(--gl-sodium);
  --mari-gauge-danger: var(--gl-red);
  --mari-game-combat-bg: #3a1410;
  --mari-game-combat-bg-hover: #521c15;
  --mari-game-combat-border: var(--gl-red);
  --mari-game-combat-text: #ffd9d2;
  --mari-lore-constant: var(--gl-sodium);
  --mari-lore-selective: var(--gl-neon);
  --mari-lore-normal: #8f8878;

  /* backdrop: the splash page behind the gutters */
  --mari-app-backdrop-layers: url("theme:city-night.webp") center bottom / cover no-repeat, var(--gl-gutter);
  --mari-home-wash: linear-gradient(180deg, rgb(7 8 10 / 0.45), rgb(7 8 10 / 0.12) 40%, rgb(7 8 10 / 0.5));
  --mari-home-art: none;
  --mari-chat-wash: linear-gradient(90deg, rgb(7 8 10 / 0.55), rgb(7 8 10 / 0.15) 22%, rgb(7 8 10 / 0.15) 78%, rgb(7 8 10 / 0.55));
  --mari-page-veil: rgb(10 11 13 / 0.9);
  --mari-scrim: rgb(0 0 0 / 0.72);
  --mari-stage-empty-bg: url("theme:city-night.webp") center / cover, #07080a;
  --mari-chat-header-bg: none;

  /* the top bar is the page masthead: a roofline along its bottom edge */
  --mari-top-bar-bg: url("theme:roofline.webp") left bottom / auto 30px repeat-x, linear-gradient(180deg, #0c0d10 0%, #1d1912 38%, #5a3d14 82%, #7a5218 100%);
  --mari-top-bar-plate: rgb(12 13 16 / 0.92);
  --mari-top-bar-plate-radius: 0;
  --mari-top-bar-plate-active: #2a2214;

  /* reading */
  --mari-chat-column: 50rem;
  --mari-message-measure: 70ch;
  --mari-chat-font-size: 18.5px;
  --mari-chat-line-height: 1.58;
  --mari-paragraph-gap: 0.7em;
  --mari-dialogue-weight: 400;
  --mari-dialogue-color: #ffd58a;
  --mari-text-outline: 0;
  --mari-msg-head-rule: none;
  --mari-message-time: var(--gl-dim);
  --mari-message-actions: var(--gl-mute);
  --mari-swipe-counter: var(--gl-mute);
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bg: var(--gl-paper-solid);
  --mari-phone-avatar: hidden;
  --mari-composer-placeholder: "The next panel...";
  --mari-min-ui-text: 12px;
  --mari-toast-font-size: 15px;
  --mari-chat-row-art-opacity: 0;
  --mari-card-art-placeholder: url("theme:card-placeholder.webp") center / cover, linear-gradient(160deg, #1b1d22, #0b0c0e);
  --mari-user-avatar-image: url("theme:hat-silhouette.webp");
  --mari-user-avatar-placeholder: radial-gradient(circle at 50% 30%, #2a2d33, #0b0c0e);
  --mari-art-saturation-1: 18%;
  --mari-art-lightness-1: 26%;
  --mari-art-saturation-2: 22%;
  --mari-art-lightness-2: 14%;
  --mari-focus-ring-color: var(--gl-sodium);

  /* Home widgets: the page of panels */
  --mari-home-widget-radius: 0;
  --mari-home-widget-border: var(--gl-ink);
  --mari-home-widget-border-width: 0;
  --mari-home-widget-bg: transparent;
  --mari-home-widget-font: var(--gl-ui);
  --mari-home-widget-title-font: var(--gl-display);
  --mari-home-widget-title-size: 1.4rem;
  --mari-home-widget-title-color: var(--gl-text);
  --mari-home-widget-eyebrow-size: 0.8rem;
  --mari-home-widget-eyebrow-color: var(--gl-caption-ink);
  --mari-home-widget-text-size: 0.95rem;
  --mari-home-widget-muted: var(--gl-mute);
  --mari-home-widget-glow: transparent;

  /* weather: this city is famous for its storms */
  --mari-weather-style: smooth;
  --mari-weather-rain-color: #9fb4c2;
  --mari-weather-rain-length: 2.3;
  --mari-weather-strength: 0.95;
  --mari-weather-speed: 1.2;
  --mari-weather-tint-strength: 0.55;
  --mari-weather-lightning-color: #e2ecff;
  --mari-weather-lightning-bolt: 2.4;
  --mari-weather-snow-color: #d8d6cf;
  --mari-weather-snow-size: 0.9;
  --mari-weather-fog-color: #4a4536;
  --mari-weather-hail-color: #c9d2d8;
  --mari-weather-ash-color: #6a6660;
  --mari-weather-ember-color: #f0b04a;
  --mari-weather-dust-color: #c8a46a;
  --mari-weather-dust-size: 0.7;
  --mari-weather-star-color: #c8c2b0;
  --mari-weather-star-size: 0.6;
  --mari-weather-firefly-color: #f0b04a;
  --mari-weather-moon-color: #d9cfae;
  --mari-weather-moon-size: 0.8;
  --mari-weather-sun: none;
}

/* DAY: grim overcast newsprint */
:root[data-theme="light"] {
  --gl-gutter: #c9ccc4;
  --gl-paper: rgb(235 231 220 / 0.96);
  --gl-paper-solid: #ebe7dc;
  --gl-paper-2: #dfdbcf;
  --gl-ink: #111113;
  --gl-key: transparent;
  --gl-text: #17171a;
  --gl-mute: #363530;
  --gl-dim: #3f3e39;
  --gl-caption: #f0c45a;
  --gl-caption-ink: #111111;
  --gl-sodium: #8a4b00;
  --gl-neon: #0f6b62;
  --gl-red: #a3241a;
  --gl-balloon: #fbfaf5;
  --gl-balloon-ink: #121214;
  --gl-line: rgb(17 17 19 / 0.18);
  --gl-halftone: url("theme:halftone-ink.png");
  --gl-grain: url("theme:grain-dark.png");

  --primary-foreground: #fff7e6;
  --secondary: #dcd8cc;
  --muted: #dfdbcf;
  --accent: #d4d0c4;
  --destructive: #a3241a;
  --border: rgb(17 17 19 / 0.28);
  --input: rgb(17 17 19 / 0.32);
  --sidebar: rgb(170 172 164 / 0.96);
  --sidebar-border: #111113;
  --sidebar-accent: #9a9d95;
  --ov-hover: rgb(17 17 19 / 0.06);
  --ov-active-bg: rgb(240 196 90 / 0.45);
  --mari-status-online: #1d7a45;
  --mari-status-offline: #77746c;
  --mari-gauge-ok: #1d7a45;
  --mari-game-combat-bg: #f3d9d4;
  --mari-game-combat-bg-hover: #ecc6be;
  --mari-game-combat-text: #6d140c;
  --mari-lore-normal: #77746c;

  --mari-app-backdrop-layers: url("theme:city-day.webp") center bottom / cover no-repeat, var(--gl-gutter);
  --mari-home-wash: linear-gradient(180deg, rgb(201 204 196 / 0.5), rgb(201 204 196 / 0.15) 40%, rgb(201 204 196 / 0.5));
  --mari-chat-wash: linear-gradient(90deg, rgb(160 164 156 / 0.45), transparent 22%, transparent 78%, rgb(160 164 156 / 0.45));
  --mari-page-veil: rgb(181 181 171 / 0.93);
  --mari-scrim: rgb(40 42 40 / 0.55);
  --mari-stage-empty-bg: url("theme:city-day.webp") center / cover, #c9ccc4;
  --mari-top-bar-bg: url("theme:roofline.webp") left bottom / auto 30px repeat-x, linear-gradient(180deg, #e2e3de, #b4b8b0);
  --mari-top-bar-plate: rgb(235 231 220 / 0.94);
  --mari-dialogue-color: #6e3a00;
  --mari-card-art-placeholder: url("theme:card-placeholder.webp") center / cover, linear-gradient(160deg, #bfc2bb, #8e938c);
  --mari-user-avatar-placeholder: radial-gradient(circle at 50% 30%, #d6d4cc, #9a9890);

  --mari-weather-rain-color: #4d5a63;
  --mari-weather-strength: 1.1;
  --mari-weather-tint-strength: 0.45;
  --mari-weather-lightning-color: #f4f7ff;
  --mari-weather-snow-color: #5f6870;
  --mari-weather-fog-color: #8c8a78;
  --mari-weather-hail-color: #5f6870;
  --mari-weather-dust-color: #6b6a63;
  --mari-weather-firefly-color: #8a4b00;
}

/* weather-aware splash pages */
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="rain"] { --mari-app-backdrop-layers: url("theme:city-night-storm.webp") center bottom / cover no-repeat, var(--gl-gutter); }
:root[data-theme="dark"][data-mari-weather="snow"],
:root[data-theme="dark"][data-mari-weather="hail"] { --mari-app-backdrop-layers: url("theme:city-night-snow.webp") center bottom / cover no-repeat, var(--gl-gutter); }
:root[data-theme="light"][data-mari-weather="snow"],
:root[data-theme="light"][data-mari-weather="hail"] { --mari-app-backdrop-layers: url("theme:city-day-snow.webp") center bottom / cover no-repeat, var(--gl-gutter); }
:root[data-theme="light"][data-mari-weather="storm"],
:root[data-theme="light"][data-mari-weather="rain"] {
  --mari-app-backdrop-layers: linear-gradient(180deg, rgb(28 33 40 / 0.72), rgb(40 45 50 / 0.5)), url("theme:city-day.webp") center bottom / cover no-repeat;
  --mari-weather-tint-strength: 0.75;
  --mari-weather-rain-color: #2c363d;
}
:root[data-theme="dark"][data-mari-weather="fog"] {
  --mari-app-backdrop-layers: linear-gradient(0deg, rgb(74 69 54 / 0.85), rgb(74 69 54 / 0.35) 45%, rgb(30 30 28 / 0.5)), url("theme:city-night.webp") center bottom / cover no-repeat;
}
:root[data-theme="light"][data-mari-weather="fog"] {
  --mari-app-backdrop-layers: linear-gradient(0deg, rgb(200 198 182 / 0.9), rgb(200 198 182 / 0.45) 50%, rgb(190 192 186 / 0.55)), url("theme:city-day.webp") center bottom / cover no-repeat;
}
:root { --mari-weather-leaf-image: url("theme:scrap-1.png") url("theme:scrap-2.png") url("theme:scrap-3.png") url("theme:scrap-4.png"); --mari-weather-leaf-size: 0.9; }

/* phones and tall tablets get the vertical splash page */
@media (max-aspect-ratio: 4/5) {
  :root[data-theme="dark"] { --mari-app-backdrop-layers: url("theme:city-phone-night.webp") center bottom / cover no-repeat, var(--gl-gutter); }
  :root[data-theme="light"] { --mari-app-backdrop-layers: url("theme:city-phone-day.webp") center bottom / cover no-repeat, var(--gl-gutter); }
  :root { --gl-cut: clamp(8px, 10%, 18px); --gl-cut-pad: 18px; }
}

/* ---------- 2. house rules --------------------------------------------- */
img[data-mari-part="backdrop"][data-default-background] { opacity: 0 !important; }
.mari-app.geometric-grid, .mari-app.noise-bg { background-image: none !important; }
[class*="blur-3xl"], [class*="blur-2xl"], .mari-home-browser-starfield { display: none !important; }
::selection { background: var(--gl-caption); color: #111; }
body { -webkit-font-smoothing: antialiased; }

/* the caption box: the theme's one recurring label shape */
.gl-caption-shape,
[data-mari-part="message"] .mari-message-name,
[data-mari-part="home-widget-eyebrow"],
.ov-libnav__title,
.mari-sidebar-header h2 {
  font-family: var(--gl-display) !important;
  font-weight: 700 !important;
  text-transform: uppercase;
  letter-spacing: 0.06em !important;
  background: var(--gl-caption) !important;
  color: var(--gl-caption-ink) !important;
  -webkit-text-stroke: 0 !important;
  border: 2px solid var(--gl-ink);
  padding: 2px 9px 1px !important;
  line-height: 1.25 !important;
}

/* ---------- 3. top bar: the masthead ----------------------------------- */
[data-component="TopBar"] {
  border-bottom: 4px solid var(--gl-ink) !important;
  box-shadow: 0 1px 0 var(--gl-key) !important;
  font-family: var(--gl-display);
}
[data-component="TopBar"] .ov-tab,
[data-component="TopBar"] .ov-text-btn {
  border-radius: 0 !important;
  font-family: var(--gl-display) !important;
  font-weight: 700 !important;
  font-size: 15px !important;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
[data-component="TopBar"] .ov-tab.is-on,
[data-component="TopBar"] .ov-text-btn.is-on {
  background: var(--gl-caption) !important;
  color: #111 !important;
  box-shadow: inset 0 0 0 2px var(--gl-ink) !important;
}
[data-component="TopBar"] :is(.ov-tab, .ov-text-btn).is-on * { color: #111 !important; }
[data-component="TopBar"] .ov-icon-btn { border-radius: 0 !important; }

/* ---------- 4. chats sidebar: a vertical strip ------------------------- */
[data-component="ChatSidebar"] {
  border-right: 4px solid var(--gl-ink) !important;
}
[data-component="RightPanelDesktop"] {
  border-left: 4px solid var(--gl-ink) !important;
}
.mari-sidebar-header h2 { font-size: 15px !important; }
.mari-sidebar-header .h-6.w-6 { border-radius: 0 !important; }
.mari-chrome-segmented { border-radius: 0 !important; border: 2px solid var(--gl-ink) !important; background: var(--gl-paper) !important; padding: 2px !important; }
.mari-chrome-segmented__button { border-radius: 0 !important; font-size: 12px !important; font-weight: 700 !important; }
.mari-chrome-segmented__button--selected { background: var(--gl-caption) !important; color: #111 !important; }
.mari-chrome-segmented__button--selected * { color: #111 !important; }
.ov-new-pill { border-radius: 0 !important; background: var(--gl-caption) !important; color: #111 !important; border: 2px solid var(--gl-ink) !important; font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.05em; font-weight: 700 !important; }
.ov-new-pill * { color: #111 !important; }

[data-chat-row] {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper) !important;
  margin-bottom: 6px;
  min-height: 46px;
  --tw-ring-color: transparent !important;
}
[data-chat-row]:hover { background: var(--gl-paper-2) !important; }
[data-chat-row][data-selected="true"] {
  background: linear-gradient(90deg, var(--gl-caption) 0 7px, var(--gl-paper-2) 7px) !important;
  border-width: 2px 2px 3px 2px !important;
}
[data-chat-row] .mari-chrome-text { font-size: 15px !important; color: var(--gl-text) !important; }
[data-chat-row] .mari-chrome-accent-text-muted { font-size: 12px !important; color: var(--gl-mute) !important; }
[data-chat-row] span[class*="overflow-hidden"][class*="rounded"] { border-radius: 0 !important; }
[data-chat-row] .mari-chrome-accent-progress { display: none !important; }

/* Library nav */
.ov-libnav__title { display: inline-block; font-size: 20px !important; }
.ov-libnav__item { border-radius: 0 !important; font-size: 15px !important; }
.ov-libnav__item:hover { background: var(--ov-hover) !important; box-shadow: inset 4px 0 0 var(--gl-caption); }

/* ---------- 5. the panel: square ink frame, one slanted edge ----------- */
/* Built from backgrounds and a clip-path only, so it never covers anything. */
:root {
  --gl-panel-bg:
    var(--gl-grain) 0 0 / 192px repeat,
    linear-gradient(to bottom right, var(--gl-paper-solid) calc(50% - var(--gl-frame)), var(--gl-ink) calc(50% - var(--gl-frame)) 50%, transparent 50%) left bottom / 100% var(--gl-cut) no-repeat,
    linear-gradient(var(--gl-paper-solid), var(--gl-paper-solid)) left top / 100% calc(100% - var(--gl-cut) + 1px) no-repeat;
  --gl-panel-clip: polygon(0 0, 100% 0, 100% calc(100% - var(--gl-cut)), 0 100%);
  --gl-panel-bg-flip:
    var(--gl-grain) 0 0 / 192px repeat,
    linear-gradient(to bottom left, var(--gl-paper-solid) calc(50% - var(--gl-frame)), var(--gl-ink) calc(50% - var(--gl-frame)) 50%, transparent 50%) left bottom / 100% var(--gl-cut) no-repeat,
    linear-gradient(var(--gl-paper-solid), var(--gl-paper-solid)) left top / 100% calc(100% - var(--gl-cut) + 1px) no-repeat;
  --gl-panel-clip-flip: polygon(0 0, 100% 0, 100% 100%, 0 calc(100% - var(--gl-cut)));
}

/* ---------- 6. roleplay: panels and balloons --------------------------- */
[data-chat-mode] { background-image: none !important; }
.rpg-overlay, .rpg-vignette { display: none !important; }
[data-mari-part="message"] * { -webkit-text-stroke: 0 !important; }

[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) {
  border-radius: 0 !important;
  border: var(--gl-frame) solid var(--gl-ink) !important;
  border-bottom: 0 !important;
  box-shadow: inset 0 1px 0 var(--gl-key) !important;
  background: var(--gl-panel-bg) !important;
  clip-path: var(--gl-panel-clip);
  padding-bottom: var(--gl-cut-pad);
  backdrop-filter: none !important;
}
.mari-messages-scroll > :nth-child(4n+3) [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user),
.mari-messages-scroll > :nth-child(4n+3)[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) {
  background: var(--gl-panel-bg-flip) !important;
  clip-path: var(--gl-panel-clip-flip);
}
[data-mari-part="message"] .mari-rp-bubble > .px-4 { padding: 0 22px 6px !important; }

/* the name: a caption box pinned in the panel's top-left corner */
[data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="inside"] {
  margin: 0 -22px 12px !important;
  padding: 0 12px 0 0 !important;
  border-bottom: 0 !important;
  align-items: flex-start !important;
  gap: 10px;
}
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble .mari-message-name {
  border-width: 0 2px 2px 0 !important;
  font-size: 15px !important;
  padding: 4px 12px 3px !important;
}
[data-mari-part="message"] [data-mari-part="time"] {
  font-family: var(--gl-display) !important;
  font-size: 13px !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--mari-message-time) !important;
  padding-top: 5px;
}
[data-mari-part="message"] .mari-message-content {
  font-family: var(--gl-read) !important;
  color: var(--gl-text);
}
[data-mari-part="message"] .mari-message-content em { color: var(--gl-mute); }
:root[data-theme="light"] [data-mari-part="message"] .mari-message-content em { color: #3c3b36; }

/* the latest panel gets a misregistered amber print edge */
[data-mari-part="message"][data-latest]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) {
  border-left-width: 7px !important;
  border-left-color: var(--gl-caption) !important;
}

/* avatars: tilted inset close-ups */
[data-mari-part="message"] [data-mari-part="avatar"] button,
[data-mari-part="message"] [data-mari-part="avatar"] > div > button {
  border-radius: 0 !important;
  box-shadow: 0 0 0 3px var(--gl-ink), 4px 4px 0 3px var(--gl-ink) !important;
  --tw-ring-color: transparent !important;
  transform: rotate(-3deg);
}
[data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] button { transform: rotate(3deg); }
.rpg-avatar-glow { filter: none !important; box-shadow: none !important; }
.rpg-avatar-glow::before, .rpg-avatar-glow::after { display: none !important; }

/* your turns: a speech balloon with a tail */
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user {
  border-radius: 26px !important;
  background: var(--gl-balloon) !important;
  border: 3px solid var(--gl-ink) !important;
  box-shadow: none !important;
  color: var(--gl-balloon-ink) !important;
  overflow: visible !important;
}
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user .mari-message-content { color: var(--gl-balloon-ink) !important; font-family: var(--gl-read) !important; }
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user .mari-message-content em { color: #3c3b36 !important; }
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user .mari-message-name {
  background: transparent !important; border: 0 !important; padding: 0 !important; color: #3c3b36 !important;
}
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user [data-mari-part="header"] { margin: 0 0 4px !important; padding: 0 !important; background: transparent !important; position: static !important; }
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user [data-mari-part="time"] { color: #5d5b54 !important; padding-top: 0; }
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user > .px-4 { padding: 12px 24px 12px !important; }
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::after {
  content: "";
  position: absolute;
  right: -17px;
  top: 22px;
  width: 22px;
  height: 18px;
  background: var(--gl-balloon);
  clip-path: polygon(0 0, 100% 35%, 0 100%);
  z-index: 2;
}
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::before {
  content: "";
  position: absolute;
  right: -22px;
  top: 17px;
  width: 26px;
  height: 28px;
  background: var(--gl-ink);
  clip-path: polygon(0 0, 100% 42%, 0 100%);
  z-index: 1;
}
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user [data-mari-part="actions"] :is(button, span) { color: #3c3b36 !important; }

/* scene break: a wide gutter with a LATER caption */
[data-mari-part="message"] .mari-message-content hr {
  opacity: 1 !important;
  border: 0 !important;
  height: 26px;
  margin: 18px -22px !important;
  background: var(--gl-gutter);
  position: relative;
  overflow: visible;
  box-shadow: 0 var(--gl-frame) 0 var(--gl-ink), 0 calc(var(--gl-frame) * -1) 0 var(--gl-ink),
    300px 0 0 var(--gl-gutter), 300px var(--gl-frame) 0 var(--gl-ink), 300px calc(var(--gl-frame) * -1) 0 var(--gl-ink);
}
[data-mari-part="message"] .mari-message-content hr::after {
  content: "Later";
  position: absolute;
  left: 22px;
  top: 50%;
  transform: translateY(-50%);
  font: 700 14px/1 var(--gl-display);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  background: var(--gl-caption);
  color: #111;
  border: 2px solid var(--gl-ink);
  padding: 4px 10px 3px;
}

/* chat backgrounds a user picked are printed in noir: greyscale, under a smog wash */
img[data-mari-part="backdrop"]:not([data-default-background]) { filter: grayscale(0.9) contrast(1.08) brightness(0.62); }
:root[data-theme="light"] img[data-mari-part="backdrop"]:not([data-default-background]) { filter: grayscale(0.9) contrast(0.95) brightness(1.02); }

/* message tools */
.ov-rpf__btn { border-radius: 0 !important; }

/* ---------- 7. composer: the blank next panel -------------------------- */
[data-mari-part="composer"] .mari-chat-input-box {
  border-radius: 0 !important;
  border: var(--gl-frame) solid var(--gl-ink) !important;
  background:
    linear-gradient(135deg, var(--gl-caption) 0 16px, var(--gl-ink) 16px 19px, transparent 19px) left top / 40px 40px no-repeat,
    var(--gl-paper-solid) !important;
  box-shadow: 6px 6px 0 var(--gl-ink) !important;
  backdrop-filter: none !important;
}
[data-mari-part="composer"] .mari-chat-input-box:focus-within { box-shadow: 6px 6px 0 var(--gl-caption) !important; }
[data-mari-part="composer"] textarea { font-family: var(--gl-read) !important; font-size: 17px !important; color: var(--gl-text) !important; }
[data-mari-part="composer"] textarea::placeholder { color: var(--gl-dim) !important; font-style: italic; }
[data-mari-part="composer"] button { border-radius: 0 !important; }
[data-mari-part="composer"] .mari-chat-send-btn { background: var(--gl-caption) !important; color: #111 !important; border: 2px solid var(--gl-ink) !important; }
[data-mari-part="composer"] img { border-radius: 0 !important; }

/* ---------- 8. conversation: a strip of thin panels -------------------- */
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-name {
  font-size: 14px !important; border-width: 2px !important;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] .mari-message-name {
  background: var(--gl-balloon) !important; color: var(--gl-balloon-ink) !important;
}
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-content { font-size: 17px !important; }
[data-chat-mode="conversation"] [data-mari-part="avatar"] button { border-radius: 0 !important; box-shadow: 0 0 0 2px var(--gl-ink) !important; }
[data-mari-part="chat-header"] > * { border-radius: 0 !important; }

/* ---------- 9. Home: a page of panels ---------------------------------- */
[data-component="HomeBrowserHub.HomePage"] { background: transparent !important; }
:root[data-overhaul] .mari-home-hero h1 {
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  font-size: clamp(2.6rem, 4.4vw, 4rem) !important;
  line-height: 0.95 !important;
  color: var(--gl-text) !important;
  text-shadow: 3px 3px 0 var(--gl-ink);
}
:root[data-overhaul] .mari-home-hero {
  background: url("theme:gargoyle.webp") right -10px bottom -6px / auto 190px no-repeat !important;
  padding-right: 190px !important;
}
:root[data-overhaul="mobile"] .mari-home-hero { background-size: auto 120px !important; padding-right: 0 !important; }
:root[data-theme="light"][data-overhaul] .mari-home-hero h1 { text-shadow: 2px 2px 0 rgb(255 255 255 / 0.6); }
.ov-home-modes > *, .ov-home-hero-actions .ov-btn {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 15px !important;
  box-shadow: 3px 3px 0 var(--gl-ink) !important;
}

[data-mari-part="home-widget"] {
  border: var(--gl-frame) solid var(--gl-ink) !important;
  border-bottom: 0 !important;
  border-radius: 0 !important;
  background: var(--gl-panel-bg) !important;
  clip-path: var(--gl-panel-clip);
  padding-bottom: calc(var(--gl-cut-pad) + 14px) !important;
  box-shadow: none !important;
}
.mari-home-feed-grid > :nth-child(even) [data-mari-part="home-widget"],
.mari-home-feed-grid > [data-mari-part="home-widget"]:nth-child(even) {
  background: var(--gl-panel-bg-flip) !important;
  clip-path: var(--gl-panel-clip-flip);
}
.mari-home-widget::before { display: none !important; }
.mari-home-widget { --mari-home-widget-hover-transform: none; --mari-home-widget-hover-filter: none; }
[data-mari-part="home-widget-eyebrow"] {
  display: inline-block !important;
  align-self: flex-start;
  margin: 0 0 6px 0 !important;
  font-size: 13px !important;
}
[data-mari-part="home-widget-title"] {
  line-height: 1.1 !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--gl-text) !important;
}
[data-mari-part="home-widget-text"], .mari-home-widget-shortcut__description { color: var(--gl-mute) !important; }
.ov-recent button { border-radius: 0 !important; border-bottom: 1px solid var(--gl-line) !important; }
.ov-recent__avatar { border-radius: 0 !important; box-shadow: 0 0 0 2px var(--gl-ink); }
.ov-recent__text strong { font-size: 15px !important; }
.ov-recent__text small { font-size: 14px !important; color: var(--gl-mute) !important; }
.ov-recent__mode { border-radius: 0 !important; font-family: var(--gl-display); text-transform: uppercase; letter-spacing: 0.06em; font-size: 13px !important; }
.ov-recent__time { font-size: 13px !important; color: var(--gl-mute) !important; }
[data-mari-part="home-widget"] .mari-chrome-control { border-radius: 0 !important; }

/* ---------- 10. splash dialogs: Ctrl+K, dialogs, windows --------------- */
[data-component="GlobalOmnibar.Panel"],
.mari-modal-panel,
[data-component="OnboardingTutorial.Card"],
.mari-window {
  border-radius: 0 !important;
  border: 5px solid var(--gl-ink) !important;
  box-shadow: 10px 10px 0 rgb(0 0 0 / 0.55), inset 0 0 0 1px var(--gl-key) !important;
  background:
    var(--gl-halftone) right top / 200px 200px no-repeat,
    var(--gl-paper-solid) !important;
}
[data-component="GlobalOmnibar.Panel"] > div.pointer-events-none:first-child { display: none !important; }
.mari-modal-backdrop { backdrop-filter: none !important; }
.mari-modal-panel, [data-component="OnboardingTutorial.Card"] { background: var(--gl-paper-solid) !important; }
.mari-modal-panel .marinara-chat-popover__header { background: var(--gl-halftone) right 30px top -40px / 140px 140px no-repeat !important; }
/* the dialog's title becomes a caption box pinned into the corner */
.mari-modal-panel .marinara-chat-popover__header { border-bottom: 3px solid var(--gl-ink) !important; padding-left: 0 !important; padding-top: 0 !important; align-items: flex-start !important; }
.mari-modal-panel .marinara-chat-popover__header :is(h2, h3, [id$="title"], span.font-semibold, .font-semibold):first-child {
  font-family: var(--gl-display) !important;
  font-size: 17px !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: var(--gl-caption);
  color: #111 !important;
  border: solid var(--gl-ink);
  border-width: 0 3px 3px 0;
  padding: 6px 14px 5px;
}
.mari-modal-panel button { border-radius: 0 !important; }
[data-component="GlobalOmnibar.Panel"] li,
[data-component="GlobalOmnibar.Panel"] button { border-radius: 0 !important; }
[role="menu"], [role="listbox"], [data-sonner-toast] {
  border-radius: 0 !important;
  border: 3px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  box-shadow: 5px 5px 0 rgb(0 0 0 / 0.5) !important;
}

/* ---------- 11. pages, cards, controls --------------------------------- */
.ov-btn, .ov-edbtn, .mari-chrome-control { border-radius: 0 !important; }
.ov-btn--primary, .ov-btn--accent, .ov-edbtn--accent, .mari-chrome-control--primary {
  background: var(--gl-caption) !important;
  color: #111 !important;
  border: 2px solid var(--gl-ink) !important;
  box-shadow: 3px 3px 0 var(--gl-ink) !important;
}
.ov-card { border-radius: 0 !important; border: 3px solid var(--gl-ink) !important; box-shadow: 5px 5px 0 rgb(0 0 0 / 0.35) !important; }
.ov-card__art, [data-mari-part="card-art"] { border-radius: 0 !important; }
:is(input, textarea, select):not([type="range"]):not([type="checkbox"]):not([type="radio"]) { border-radius: 0 !important; }
[data-settings-switch-track] { border-radius: 0 !important; border: 2px solid var(--gl-ink) !important; }
[data-settings-switch-thumb] { border-radius: 0 !important; }
[data-settings-switch-track][data-checked] { background: var(--gl-caption) !important; }
[data-settings-switch-track][data-checked] [data-settings-switch-thumb] { background: #111 !important; }
.ov-switch, .ov-switch span { border-radius: 0 !important; }
.ov-switch.is-on { background: var(--gl-caption) !important; }
:root[data-overhaul] :is([data-component="OverhaulSettingsPage"], [data-component="OverhaulLibraryPage"]) :is(h1, h2),
:root[data-overhaul] [data-mari-part="page-title"] {
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

/* ---------- 12. game: the bottom narration panel ----------------------- */
[data-mari-part="message"][data-game-narration] {
  border-radius: 0 !important;
  border: var(--gl-frame) solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  box-shadow: 8px 8px 0 rgb(0 0 0 / 0.6) !important;
  backdrop-filter: none !important;
}
[data-mari-part="game-hud"], [data-mari-part="game-tools"] button { border-radius: 0 !important; }
[data-mari-part="game-hud"] { border: 3px solid var(--gl-ink) !important; background: var(--gl-paper-solid) !important; }

/* ---------- 13. phone and tablet --------------------------------------- */
:root[data-overhaul="mobile"] [data-mari-part="message"] .mari-rp-bubble > .px-4 { padding: 0 16px 4px !important; }
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="inside"] { margin: 0 -16px 10px !important; }
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::before,
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::after { display: none; }

/* game narration: caption tab, framed prose, square tools */
[data-mari-part="message"][data-game-narration] > div:first-child > span:first-child,
[data-mari-part="message"][data-game-narration] .mb-2 > span.rounded-full {
  font-family: var(--gl-display) !important;
  font-size: 14px !important;
  letter-spacing: 0.1em !important;
  border-radius: 0 !important;
  background: var(--gl-caption) !important;
  color: #111 !important;
  border: 2px solid var(--gl-ink);
  padding: 3px 10px 2px !important;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  font-family: var(--gl-read);
}
[data-mari-part="message"][data-game-narration] .game-narration-prose .text-sm { font-size: 18px !important; line-height: 1.55 !important; }
[data-mari-part="message"][data-game-narration] button { border-radius: 0 !important; }
.mari-game-meta, .mari-game-active-action { border-radius: 0 !important; }

/* phone and tablet top bar: square plates */
.ovm-topbar :is(.ovm-title, .ovm-icon-btn, .ovm-stack-btn, .ovm-tabs-icon) { border-radius: 0 !important; }
.ovm-topbar { border-bottom: 4px solid var(--gl-ink) !important; }
.ovm-title__text { font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.04em; font-size: 16px !important; }

/* Settings: section names become caption boxes, chips go square */
[data-component="OverhaulSettingsPage"] div.inline-flex.items-center.text-xs.font-semibold {
  font-family: var(--gl-display) !important;
  font-size: 14px !important;
  letter-spacing: 0.1em !important;
  background: var(--gl-caption);
  color: #111 !important;
  border: 2px solid var(--gl-ink);
  padding: 2px 9px 1px;
}
[data-component="OverhaulSettingsPage"] div.inline-flex.items-center.text-xs.font-semibold * { color: #111 !important; }
.ov-chip { border-radius: 0 !important; }
.ov-chip.is-on, .ov-chip[aria-pressed="true"] { background: var(--gl-caption) !important; color: #111 !important; border-color: var(--gl-ink) !important; }
:root[data-overhaul] [data-component="OverhaulCardGallery"] h1,
:root[data-overhaul] [data-component="OverhaulLibraryPage"] h1,
:root[data-overhaul] [data-mari-part="page-title"] { font-family: var(--gl-display) !important; text-transform: uppercase; }

/* Library cards: the art is the panel, the name a caption strip under it */
.ov-card { background: var(--gl-paper-solid) !important; padding-bottom: 8px; }
.ov-card__name, .ov-card__tags { padding-inline: 10px !important; }
.ov-card__name { font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.04em; font-size: 17px !important; margin-top: 6px; }
.ov-card__art { border-bottom: 3px solid var(--gl-ink) !important; }

/* conversation: every line is a thin strip panel with a gutter between */
[data-chat-mode="conversation"] [data-mari-part="message"] > .mari-message {
  background: var(--gl-paper) !important;
  border: 2px solid var(--gl-ink) !important;
  border-left-width: 2px !important;
  padding-block: 8px !important;
  margin: 0 16px 6px;
  width: auto !important;
}
[data-chat-mode="conversation"] [data-mari-part="message"]:hover > .mari-message { box-shadow: inset 5px 0 0 var(--gl-caption) !important; }
[data-chat-mode="conversation"] .mari-messages-scroll,
[data-chat-mode="conversation"] [class*="max-w-"] > [data-mari-part="message"] { --tw-ring-color: transparent; }
[data-mari-part="chat-header"] { font-family: var(--gl-ui); }

/* phones: the name line sits above the panel on a square paper strip */
[data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] {
  border-radius: 0 !important;
  background: var(--gl-paper-solid) !important;
  border: 2px solid var(--gl-ink);
  border-bottom: 0;
  padding: 0 8px 0 0 !important;
  align-self: flex-start;
}
[data-mari-part="message"][data-message-role="user"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] { align-self: flex-end; padding: 0 0 0 8px !important; }
[data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] .mari-message-name { border-width: 0 2px 0 0 !important; }
[data-mari-part="message"][data-message-role="user"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] .mari-message-name { border-width: 0 0 0 2px !important; }

/* ==========================================================================
   ROUND 2
   ========================================================================== */

/* ---------- 14. the pinned name: a solid paper strip with an ink rule ---- */
[data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) .ov-rpmsg__head {
  background: var(--gl-paper-solid) !important;
  box-shadow: 0 3px 0 var(--gl-ink) !important;
  container-type: scroll-state;
  padding-bottom: 4px !important;
  margin-bottom: 12px !important;
  z-index: 6;
}
/* LATER sits at the right end of its gutter, so it never stacks under the pinned name */
[data-mari-part="message"] .mari-message-content hr::after { left: auto; right: 22px; }

/* the swipe and regenerate tools: a small square ink plate tucked under the panel */
[data-mari-part="message"] .ov-rpf--below {
  background: var(--gl-paper-solid) !important;
  border: 2px solid var(--gl-ink) !important;
  box-shadow: 3px 3px 0 var(--gl-ink) !important;
  border-radius: 0 !important;
  padding: 1px 2px !important;
}
[data-mari-part="message"] .ov-rpf--below :is(button, .ov-rpf__count) { border-radius: 0 !important; color: var(--gl-text) !important; }
[data-mari-part="message"] .ov-rpf--below .ov-rpf__count { font-family: var(--gl-display) !important; font-size: 14px !important; letter-spacing: 0.05em; }

/* ---------- 15. nothing peeks out below the composer -------------------- */
[data-chat-mode="roleplay"] .mari-messages-scroll {
  -webkit-mask-image: linear-gradient(to top, transparent 0, transparent 72px, #000 74px);
  mask-image: linear-gradient(to top, transparent 0, transparent 72px, #000 74px);
}

/* ---------- 16. phone: full-width name strip, bigger captions ------------ */
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] {
  align-self: stretch !important;
  border: 2px solid var(--gl-ink) !important;
  border-bottom-width: 3px !important;
  box-shadow: none !important;
  container-type: scroll-state;
  padding: 0 8px 0 0 !important;
  z-index: 6;
}
:root[data-overhaul="mobile"] [data-mari-part="message"][data-message-role="user"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"] {
  align-self: flex-end !important; padding: 0 0 0 8px !important; box-shadow: none !important;
}
:root[data-overhaul="mobile"] [data-mari-part="message"] .mari-message-name { font-size: 14px !important; padding: 3px 10px 2px !important; }
:root[data-overhaul="mobile"] [data-mari-part="message"] [data-mari-part="time"] { font-size: 13px !important; }
/* phone balloons keep a short inked tail */
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user { border-radius: 20px !important; }
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::before,
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::after { display: block; top: auto; }
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::before { right: 18px; bottom: -17px; width: 22px; height: 18px; clip-path: polygon(0 0, 100% 0, 85% 100%); }
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble--user::after { right: 22px; bottom: -11px; width: 15px; height: 14px; clip-path: polygon(0 0, 100% 0, 80% 100%); }
:root[data-overhaul="mobile"] [data-mari-part="message"][data-message-role="user"]:not([data-vn]) { margin-bottom: 26px !important; }

/* ---------- 17. phone composer: the tools fold into one "+" plate -------- */
:root[data-overhaul="mobile"] [data-mari-part="composer"] { padding-inline: 8px !important; }
:root[data-overhaul="mobile"] [data-mari-part="composer"] .mari-chat-input-box > .flex.shrink-0 { gap: 0 !important; }
:root[data-overhaul="mobile"] [data-mari-part="composer"] .mari-chat-input-box > .flex.shrink-0 > button:first-child {
  width: 34px !important; height: 34px !important;
  background: var(--gl-caption) !important; color: #111 !important;
  border: 2px solid var(--gl-ink) !important;
}
:root[data-overhaul="mobile"] [data-mari-part="composer"] .mari-chat-input-box > .flex.shrink-0 > button:first-child svg { display: none; }
:root[data-overhaul="mobile"] [data-mari-part="composer"] .mari-chat-input-box > .flex.shrink-0 > button:first-child::before {
  content: "+"; font: 700 24px/1 var(--gl-display); color: #111;
}
/* while you write, the switcher folds away and the text gets the width */
:root[data-overhaul="mobile"] [data-mari-part="composer"] .mari-chat-input-box:is(:focus-within, :has(textarea:not(:placeholder-shown))) > .flex.shrink-0 > .sm\:hidden { display: none !important; }
:root[data-overhaul="mobile"] [data-mari-part="composer"] textarea { padding-inline: 4px !important; }

/* ---------- 18. Ctrl+K: a real splash panel ----------------------------- */
[data-component="GlobalOmnibar.Panel"],
.mari-modal-panel,
[data-component="OnboardingTutorial.Card"],
.mari-window {
  outline: 2px solid var(--gl-caption);
  outline-offset: 0;
  box-shadow: 12px 12px 0 rgb(0 0 0 / 0.6), inset 0 0 0 1px var(--gl-key) !important;
}
[data-component="GlobalOmnibar.Panel"] {
  background:
    var(--gl-halftone) right -30px top 58px / 150px 150px no-repeat,
    var(--gl-grain) 0 0 / 192px repeat,
    var(--gl-paper-solid) !important;
}
[data-component="GlobalOmnibar.Panel"] header > div:first-child { border-bottom: 3px solid var(--gl-ink) !important; }
[data-component="GlobalOmnibar.Panel"] input { font-family: var(--gl-read) !important; font-size: 19px !important; }
[data-component="GlobalOmnibar.ScopeChips"] { border-bottom: 3px solid var(--gl-ink) !important; gap: 6px !important; }
[data-component="GlobalOmnibar.ScopeChips"] button {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 14px !important;
  box-shadow: 2px 2px 0 var(--gl-ink);
}
[data-component="GlobalOmnibar.ScopeChips"] button:is([aria-pressed="true"], [aria-selected="true"], [data-state="on"], [data-active="true"]) {
  background: var(--gl-caption) !important; color: #111 !important;
}
[data-component="GlobalOmnibar.Results"] section > div:first-child { padding-left: 4px !important; }
[data-component="GlobalOmnibar.Results"] section > div:first-child > svg { display: none; }
[data-component="GlobalOmnibar.Results"] section h3 {
  font-family: var(--gl-display) !important;
  font-size: 14px !important;
  letter-spacing: 0.1em !important;
  background: var(--gl-caption);
  color: #111 !important;
  border: 2px solid var(--gl-ink);
  padding: 2px 9px 1px;
}
[data-component="GlobalOmnibar.Results"] section h3 + span { color: var(--gl-mute) !important; font-size: 13px !important; }
[data-component="GlobalOmnibar.Results"] li { border-radius: 0 !important; }
[data-component="GlobalOmnibar.Results"] ul.sm\:grid { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; }
[data-component="GlobalOmnibar.Results"] ul.sm\:grid > li {
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  box-shadow: 3px 3px 0 var(--gl-ink);
}
[data-component="GlobalOmnibar.Results"] ul.sm\:grid > li > button > span:last-child { display: none !important; }
[data-component="GlobalOmnibar.Results"] .result-type-icon,
[data-component="GlobalOmnibar.Results"] .result-type-icon *,
[data-component="GlobalOmnibar.Results"] img { border-radius: 0 !important; }
[data-component="GlobalOmnibar.Results"] .result-type-icon { box-shadow: 0 0 0 2px var(--gl-ink); }
[data-component="GlobalOmnibar.Results"] li:is(:hover, [aria-selected="true"], [data-selected="true"]) { box-shadow: inset 5px 0 0 var(--gl-caption) !important; }

/* ---------- 19. the tutorial card: caption title, square ink buttons ----- */
[data-component="OnboardingTutorial.Card"] {
  background:
    var(--gl-halftone) right -30px top -30px / 200px 200px no-repeat,
    var(--gl-grain) 0 0 / 192px repeat,
    var(--gl-paper-solid) !important;
}
[data-component="OnboardingTutorial.Card"] h3 {
  display: inline-block;
  font-family: var(--gl-display) !important;
  font-size: 18px !important;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  background: var(--gl-caption);
  color: #111 !important;
  border: 2px solid var(--gl-ink);
  padding: 4px 12px 3px;
}
[data-component="OnboardingTutorial.Card"] p { font-family: var(--gl-read) !important; font-size: 16px !important; color: var(--gl-text) !important; }
[data-component="OnboardingTutorial.Card"] button { border-radius: 0 !important; font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.06em; font-size: 14px !important; }
[data-component="OnboardingTutorial.Card"] button:last-child { background: var(--gl-caption) !important; color: #111 !important; border: 2px solid var(--gl-ink) !important; box-shadow: 3px 3px 0 var(--gl-ink); }
[data-component="OnboardingTutorial.Card"] button:last-child * { color: #111 !important; }
[data-component="OnboardingTutorial.Progress"] > div { border-radius: 0 !important; }
[data-component="OnboardingTutorial.Progress"] span { font-size: 13px !important; }

/* ---------- 20. toast: a small caption panel ---------------------------- */
[data-sonner-toast] { font-family: var(--gl-ui) !important; color: var(--gl-text) !important; font-size: 15px !important; }
[data-sonner-toast] [data-title] { font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.05em; font-size: 16px !important; }
[data-sonner-toast] :is(button, [data-button], [data-close-button]) { border-radius: 0 !important; }
[data-sonner-toast] [data-button] { background: var(--gl-caption) !important; color: #111 !important; border: 2px solid var(--gl-ink) !important; font-weight: 700; }
[data-sonner-toast] [data-close-button] { background: var(--gl-paper-solid) !important; border: 2px solid var(--gl-ink) !important; color: var(--gl-text) !important; }

/* ---------- 21. game: the scene sits in the city ------------------------- */
[data-chat-mode="game"] .absolute.inset-0.z-0 {
  background: url("theme:game-stage.webp") center / cover no-repeat, url("theme:city-night.webp") center / cover no-repeat, var(--gl-gutter);
}
:root[data-theme="light"] [data-chat-mode="game"] .absolute.inset-0.z-0 {
  background: url("theme:game-stage.webp") center / cover no-repeat, url("theme:city-day.webp") center / cover no-repeat, var(--gl-gutter);
}
/* whatever scene picture the game uses is overprinted on the city in ink */
[data-chat-mode="game"] .absolute.inset-0.z-0 > .bg-cover {
  filter: grayscale(1) contrast(1.15);
  mix-blend-mode: multiply;
  opacity: 0.55;
}
:root { --mari-stage-empty-bg: url("theme:game-stage.webp") center / cover no-repeat, url("theme:city-night.webp") center / cover, #07080a; }
:root[data-theme="light"] { --mari-stage-empty-bg: url("theme:game-stage.webp") center / cover no-repeat, url("theme:city-day.webp") center / cover, #c9ccc4; }
[data-chat-mode="game"] :is(aside, [data-mari-part="game-party"], [data-mari-part="party"]) :is(button, [class*="rounded-full"], [class*="rounded-xl"], [class*="rounded-lg"]) { border-radius: 0 !important; }

/* ---------- 22. conversation: alternating slant, Today caption, framed pill */
[data-chat-mode="conversation"] [data-mari-part="message"] > .mari-message {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), 0 100%);
  border-bottom: 0 !important;
  padding-bottom: 14px !important;
  background:
    linear-gradient(to bottom right, transparent calc(50% - 2px), var(--gl-ink) calc(50% - 2px) 50%, transparent 50%) left bottom / 100% 8px no-repeat,
    var(--gl-paper) !important;
}
[data-chat-mode="conversation"] .mari-messages-scroll > :nth-child(even) [data-mari-part="message"] > .mari-message,
[data-chat-mode="conversation"] .mari-messages-scroll > [data-mari-part="message"]:nth-child(even) > .mari-message {
  clip-path: polygon(0 0, 100% 0, 100% 100%, 0 calc(100% - 8px));
  background:
    linear-gradient(to bottom left, transparent calc(50% - 2px), var(--gl-ink) calc(50% - 2px) 50%, transparent 50%) left bottom / 100% 8px no-repeat,
    var(--gl-paper) !important;
}
[data-mari-part="chat-header"] :is(button, [class*="rounded"]) { border-radius: 0 !important; }

/* ---------- 23. Library and lists: colour art printed in ink ------------- */
.ov-card__art, [data-chat-row] img, .ov-recent__avatar, [data-component="GlobalOmnibar.Results"] img {
  filter: grayscale(0.82) contrast(1.08) sepia(0.12);
  transition: filter 0.2s;
}
.ov-card:hover .ov-card__art, [data-chat-row]:hover img, [data-chat-row][data-selected="true"] img { filter: none; }

/* ---------- 24. day chrome: soot slate and newsprint --------------------- */
:root[data-theme="light"] :is([data-component="ChatSidebar"], [data-component="RightPanelDesktop"]) {
  background-image: url("theme:grain-dark.png") !important;
  background-size: 192px !important;
}

/* game side pane: a strip of panels with caption heads */
.ov-gpane {
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  border-left: 4px solid var(--gl-ink) !important;
}
.ov-gpane__tabs { border-bottom: 3px solid var(--gl-ink) !important; gap: 4px; }
.ov-gpane__tabs [role="tab"] {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  font-size: 13px !important;
  padding: 3px 6px !important;
}
.ov-gpane__tabs [role="tab"] svg { display: none; }
.ov-gpane__tabs [role="tab"].is-on { background: var(--gl-caption) !important; color: #111 !important; }
.ov-gpane__tabs [role="tab"].is-on * { color: #111 !important; }
.ov-gpane__table th, .ov-gpane__label {
  font-family: var(--gl-display) !important;
  letter-spacing: 0.1em !important;
  font-size: 14px !important;
  color: var(--gl-caption) !important;
}
:root[data-theme="light"] :is(.ov-gpane__table th, .ov-gpane__label) { color: var(--gl-sodium) !important; }
.ov-gpane__table tr { border-radius: 0 !important; }
.ov-gpane__table tbody tr { border-bottom: 2px solid var(--gl-ink) !important; }
.ov-gpane__av, .ov-gpane__av img { border-radius: 0 !important; box-shadow: 0 0 0 2px var(--gl-ink); }
.ov-gpane__table td, .ov-gpane__body p { font-size: 15px !important; }
.ov-gpane :is(button, .ov-gpane__chips > *, .ov-gpane__meter, .ov-gpane__bar) { border-radius: 0 !important; }
[data-tour="game-map"] {
  border-radius: 0 !important;
  border: 3px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  box-shadow: 5px 5px 0 rgb(0 0 0 / 0.55) !important;
}
[data-tour="game-map"] span { font-size: 13px !important; color: var(--gl-mute) !important; }

/* conversation: the date is a caption box, the header identity a small inset panel */
.mari-messages-scroll > .relative.flex > .mari-conversation-transcript-chrome-text {
  font-family: var(--gl-display) !important;
  font-size: 14px !important;
  letter-spacing: 0.12em !important;
  text-transform: uppercase;
  background: var(--gl-caption);
  color: #111 !important;
  border: 2px solid var(--gl-ink);
  padding: 3px 10px 2px;
  opacity: 1 !important;
}
[data-conversation-header-identity] > button {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  box-shadow: 3px 3px 0 var(--gl-ink) !important;
  backdrop-filter: none !important;
}
[data-conversation-header-identity] > button img, [data-conversation-header-identity] > button [class*="rounded"] { border-radius: 0 !important; }
[data-conversation-header-identity] > button > div > span:first-child { font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.05em; font-size: 15px !important; color: var(--gl-text) !important; }
[data-conversation-header-identity] > button > div > span:last-child:not(:first-child) { font-size: 13px !important; color: var(--gl-mute) !important; }

/* phone: the drawer's Home control is a square plate like the rest of the chrome */
.ovm-chats-home {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 700 !important;
  box-shadow: 2px 2px 0 var(--gl-ink);
}
/* phone Home: the mode plate sits over the time so chat names get the width */
:root[data-overhaul="mobile"] .ov-recent button {
  grid-template-columns: 2.25rem minmax(0, 1fr) auto !important;
  grid-template-rows: auto auto;
  column-gap: 0.6rem !important;
  row-gap: 2px !important;
}
:root[data-overhaul="mobile"] .ov-recent__avatar { grid-row: 1 / 3; }
:root[data-overhaul="mobile"] .ov-recent__text { grid-row: 1 / 3; grid-column: 2; }
:root[data-overhaul="mobile"] .ov-recent__mode { grid-column: 3; grid-row: 1; justify-self: end; font-size: 13px !important; letter-spacing: 0.02em; padding: 1px 5px !important; }
:root[data-overhaul="mobile"] .ov-recent__time { grid-column: 3; grid-row: 2; }


/* ==========================================================================
   ROUND 3
   ========================================================================== */
/* phone: text starts below the strip's paper fade, so the fade never tints it at rest */
:root[data-overhaul="mobile"] [data-mari-part="message"]:not([data-vn]):not([data-message-role="user"]) .mari-rp-bubble > .px-4 { padding-top: 10px !important; }

/* game toolbar: square ink plates in condensed caps */
[data-mari-part="message"][data-game-narration] button {
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  color: var(--gl-text) !important;
  box-shadow: 2px 2px 0 var(--gl-ink) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 14px !important;
}
[data-mari-part="message"][data-game-narration] .game-narration-prose button { border: 0 !important; background: transparent !important; box-shadow: none !important; }
[data-mari-part="message"][data-game-narration] button:last-child:not(.game-narration-prose button) { background: var(--gl-caption) !important; color: #111 !important; }
[data-mari-part="message"][data-game-narration] button:last-child:not(.game-narration-prose button) * { color: #111 !important; }
[data-mari-part="message"][data-game-narration] button[class*="combat"],
[data-mari-part="message"][data-game-narration] button:has(> svg + span):is([class*="red"], [class*="rose"]) { background: var(--mari-game-combat-bg) !important; color: var(--mari-game-combat-text) !important; }

/* the map float: an inset panel with a MAP caption and a sodium plate */
[data-tour="game-map"] { position: relative; padding-top: 30px !important; }
[data-tour="game-map"]::before {
  content: "Map";
  position: absolute; left: -1px; top: -1px;
  font: 700 14px/1 var(--gl-display);
  letter-spacing: 0.12em; text-transform: uppercase;
  background: var(--gl-caption); color: #111;
  border: solid var(--gl-ink); border-width: 0 2px 2px 0;
  padding: 5px 10px 4px;
}
[data-tour="game-map"] button {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-caption) !important;
  color: #111 !important;
  opacity: 1 !important;
  font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.05em; font-size: 14px !important;
  box-shadow: 2px 2px 0 var(--gl-ink);
}
[data-tour="game-map"] button * { color: #111 !important; }

/* loading skeletons: ink-framed paper bars with a sodium sweep, not indigo */
.shimmer {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink);
  background: linear-gradient(90deg, var(--gl-paper-2) 25%, rgb(240 176 74 / 0.22) 50%, var(--gl-paper-2) 75%) 0 0 / 200% 100% !important;
  animation: shimmer 1.5s ease-in-out infinite;
}
.ov-libpage__loading {
  width: fit-content; margin: 24px auto;
  font: 700 15px/1 var(--gl-display); letter-spacing: 0.12em; text-transform: uppercase;
  background: var(--gl-caption); color: #111; border: 2px solid var(--gl-ink); padding: 5px 12px 4px;
}

/* game by day: the overcast stage and a newsprint side strip */
:root[data-theme="light"] [data-chat-mode="game"] .absolute.inset-0.z-0 {
  background: url("theme:game-stage-day.webp") center / cover no-repeat, url("theme:city-day.webp") center / cover no-repeat, var(--gl-gutter);
}
:root[data-theme="light"] { --mari-stage-empty-bg: url("theme:game-stage-day.webp") center / cover no-repeat, url("theme:city-day.webp") center / cover, #c9ccc4; }
:root[data-theme="light"] [data-chat-mode="game"] .absolute.inset-0.z-0 > .bg-cover { opacity: 0.35; }
:root[data-theme="light"] .ov-gpane { background: var(--gl-grain) 0 0 / 192px repeat, #d9d6cb !important; color: var(--gl-text); }

/* day Home: the headline gets its own newsprint plate so it never sinks into a spire */
:root[data-theme="light"][data-overhaul] .mari-home-hero h1 {
  width: fit-content;
  background: rgb(235 231 220 / 0.94);
  border: 3px solid var(--gl-ink);
  box-shadow: 5px 5px 0 var(--gl-ink);
  padding: 8px 16px 4px;
  text-shadow: none;
}

/* night storm: deeper and heavier than plain night */
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="rain"] {
  --mari-app-backdrop-layers: linear-gradient(180deg, rgb(4 5 8 / 0.3), rgb(4 5 8 / 0) 50%, rgb(4 5 8 / 0.2)), url("theme:city-night-storm.webp") center bottom / cover no-repeat, var(--gl-gutter);
}

/* the last round shapes: chips, pills, tips, sheets and popovers go square */
:is(.ov-chip-btn, .ov-addchip, .ov-pill, .ov-gpane__chips span, .ov-cs-tip, .ovm-swiperow, .ovm-action-sheet__group,
    .ovm-action-sheet__field, .ov-swipe-chip, .ov-chipbox, .ov-chipbox__chip, .ov-bk__chips, .ov-bk__chip, .mari-suggestion-chip,
    .ovm-chats-new, .ovm-chats-more, .ovm-chats-menu, .ov-vw__badge, .ov-dl__badge, .ov-conn__chip, .ov-agentpage__chip) { border-radius: 0 !important; }
.ovm-sheet.is-popover:not(#ovm-x), [data-radix-popper-content-wrapper] > *, [role="dialog"][data-state] > [class*="rounded"] { border-radius: 0 !important; }
button[class*="rounded-full"]:not([data-mari-part="message"] *):not(.mari-rp-bubble--user *) { border-radius: 0 !important; }
.ov-cs-tip {
  border: 3px solid var(--gl-ink) !important;
  outline: 2px solid var(--gl-caption);
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  box-shadow: 6px 6px 0 rgb(0 0 0 / 0.55) !important;
}
.ov-cs-tip__title {
  display: inline-block;
  font-family: var(--gl-display) !important; text-transform: uppercase; letter-spacing: 0.06em; font-size: 16px !important;
  background: var(--gl-caption); color: #111 !important; border: 2px solid var(--gl-ink); padding: 3px 10px 2px;
}
.ov-cs-tip__body { font-size: 15px !important; color: var(--gl-text) !important; }
.ov-cs-tip__arrow { border-radius: 0 !important; }
.ovm-sheet.is-popover:not(#ovm-x) { border: 3px solid var(--gl-ink) !important; }

:root[data-overhaul="mobile"] [data-chat-mode="roleplay"] .mari-messages-scroll {
  -webkit-mask-image: linear-gradient(to top, transparent 0, transparent 72px, #000 74px);
  mask-image: linear-gradient(to top, transparent 0, transparent 72px, #000 74px);
}

/* ROUND 4: the paper band under a pinned name exists only while the name is stuck.
   It is solid, so text or a LATER caption under it is hidden, never ghosted. */
@container scroll-state(stuck: top) {
  [data-mari-part="message"]:not([data-vn]) [data-mari-part="header"][data-placement="outside"]::after,
  [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) .ov-rpmsg__head::after {
    content: "";
    position: absolute;
    left: -2px; right: -2px;
    top: calc(100% + 3px);
    height: 30px;
    background: linear-gradient(var(--gl-paper-solid) 0 26px, transparent 30px);
    pointer-events: none;
  }
  [data-mari-part="message"]:not([data-vn]) .mari-rp-bubble:not(.mari-rp-bubble--user) .ov-rpmsg__head::after { left: 0; right: 0; height: 18px; background: linear-gradient(var(--gl-paper-solid) 0 15px, transparent 18px); }
}

/* tablet/phone chats drawer: a solid masthead so the top bar under it never shows through,
   and its Library button is the same square plate as everywhere else */
:root[data-overhaul="mobile"] .mari-chat-sidebar > .mari-sidebar-header {
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  border-bottom: 4px solid var(--gl-ink);
  z-index: 2;
}
.ovm-stack-btn {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  box-shadow: 2px 2px 0 var(--gl-ink);
}

/* Home: the version tag gets a small plate clear of the gargoyle; the art never crosses the headline */
:root[data-overhaul] .mari-home-hero { background-position: right -10px bottom 34px !important; background-size: auto 150px !important; }
:root[data-overhaul] .mari-home-hero span.mt-1.block {
  position: relative; z-index: 1;
  width: fit-content;
  font: 700 12px/1 var(--gl-display) !important;
  letter-spacing: 0.1em;
  color: var(--gl-text) !important;
  background: var(--gl-paper-solid);
  border: 2px solid var(--gl-ink);
  padding: 3px 6px 2px;
}

/* night Home: the headline sits on an ink plate too, so no line of the art runs through it */
:root[data-theme="dark"][data-overhaul] .mari-home-hero h1 {
  width: fit-content;
  background: rgb(21 23 27 / 0.95);
  border: 3px solid var(--gl-ink);
  outline: 2px solid rgb(240 176 74 / 0.5);
  box-shadow: 5px 5px 0 var(--gl-ink);
  padding: 8px 16px 4px;
  text-shadow: none;
}



/* ==========================================================================
   ROUND 5 (1.1): one right sidebar, and one page surface for every page
   ========================================================================== */
/* Every full page (each Library page, viewer, editor, Settings, Docs) is one inked panel of
   newsprint. The veil above stays for builds without the page hook. */
[data-mari-part="page"] {
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  backdrop-filter: none !important;
}
:root[data-overhaul="on"] [data-mari-part="page"] {
  margin: 10px 12px 12px 10px;
  border: var(--gl-frame) solid var(--gl-ink);
  box-shadow: 6px 6px 0 rgb(0 0 0 / 0.45), inset 0 0 0 1px var(--gl-key);
}
/* The old per-page panels step aside inside it, so a page never gets two. */
[data-mari-part="page"] :is(.ov-gallery, .ov-settings, .ov-list, .ov-vw, .ov-ed, .ov-org, .ov-conn,
    [data-component="OverhaulLibraryPage"], [data-component="OverhaulSettingsPage"], .mari-editor-shell) {
  background: none !important;
  backdrop-filter: none !important;
}

/* The pane: the chats strip now lives on the right, so its old right-hand ink edge goes;
   the pane keeps its own heavy left edge. */
.ov-sidepane [data-component="ChatSidebar"] { border-right: 0 !important; background: transparent !important; }
:root[data-theme="light"] .ov-sidepane [data-component="ChatSidebar"] { background-image: none !important; }
.ov-sidepane { background: var(--gl-grain) 0 0 / 192px repeat; }

/* The Chats | Library switch: two square ink plates; the open one is the amber caption box
   (the job the LIBRARY caption did before, so the pane doesn't name itself twice). */
.ov-sideswitch {
  gap: 6px !important;
  margin: 10px 10px 6px !important;
  padding: 0 0 8px !important;
  border: 0 !important;
  border-bottom: 3px solid var(--gl-ink) !important;
  border-radius: 0 !important;
}
.ov-sideswitch__btn {
  height: 34px !important;
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-solid) !important;
  color: var(--gl-text) !important;
  font-family: var(--gl-display) !important;
  font-weight: 700 !important;
  font-size: 16px !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow: 3px 3px 0 var(--gl-ink);
}
.ov-sideswitch__btn:not(.is-on):hover { background: var(--gl-paper-2) !important; color: var(--gl-text) !important; }
.ov-sideswitch__btn.is-on {
  background: var(--gl-caption) !important;
  color: #111 !important;
  box-shadow: 1px 1px 0 var(--gl-ink);
  transform: translate(2px, 2px);
}
.ov-sideswitch__btn.is-on * { color: #111 !important; }
.ov-sideswitch__btn:focus-visible { outline: 3px solid var(--gl-sodium) !important; outline-offset: 2px !important; }
.ov-sidepane .ov-libnav__title { display: none !important; }

/* Phone and tablet: the side page is a full newsprint panel sliding in under the masthead */
.ovm-sidepage {
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  border-left: 4px solid var(--gl-ink);
  color: var(--gl-text);
}
.ovm-sidepage .ov-sideswitch { margin: 10px 12px 6px !important; }
.ovm-sidepage .ov-sideswitch__btn { height: 42px !important; font-size: 17px !important; }
.ovm-sidepage [data-component="ChatSidebar"] { border-right: 0 !important; background: transparent !important; }
.ovm-sidepage .ovm-stack-menu__row {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  color: var(--gl-text) !important;
  margin-bottom: 6px;
  font-size: 16px !important;
}
.ovm-sidepage .ovm-stack-menu__row:active { background: var(--gl-caption) !important; color: #111 !important; }
.ovm-sidepage__dock { border-top: 3px solid var(--gl-ink) !important; }
.ovm-sidepage .ovm-stack-menu__tile {
  border-radius: 0 !important;
  border: 2px solid var(--gl-ink) !important;
  background: var(--gl-paper-2) !important;
  color: var(--gl-text) !important;
  font-family: var(--gl-display) !important;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 14px !important;
  box-shadow: 2px 2px 0 var(--gl-ink);
}
.ovm-sidepage .ovm-tabs-icon { border-radius: 0 !important; }
.ovm-stack-btn.is-on { background: var(--gl-caption) !important; color: #111 !important; }
.ovm-stack-btn.is-on * { color: #111 !important; }

/* Editor headers: a solid newsprint strip ruled in ink, never a grey glass band */
[data-mari-part="page"] .mari-editor-header {
  background: var(--gl-grain) 0 0 / 192px repeat, var(--gl-paper-solid) !important;
  backdrop-filter: none !important;
  border-bottom: 3px solid var(--gl-ink) !important;
}
/* Connections: the "Main" job tag is a caption box, not red on pink */
.ov-conn__chip.is-main {
  background: var(--gl-caption) !important;
  color: #111 !important;
  border: 1.5px solid var(--gl-ink);
  border-radius: 0 !important;
  font-weight: 700;
}
